/*
 * A266974  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 78" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266974
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) is the nth value in the triangle read by rows of
 * elementary cellular automaton Rule 78 starting from a single ON cell.
 *
 * The triangle has odd lengths: row r has length 2r+1 and the first
 * cell of row r is at global index r^2.  This implementation keeps
 * a cached bitset of all cells that have been generated and memoises
 * the evolution using a rolling two‑row approach with a coordinate
 * offset so that neighbour look‑ups are O(1).
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* cache: one bit per cell */
static uint64_t *cache_bits = NULL;
static size_t cache_words = 0;          /* number of 64‑bit words allocated */
static idx_t cached_cells = 0;          /* next free global index */

/* current row (previous) */
static uint8_t *prev_row = NULL;
static size_t prev_len = 0;             /* length of prev_row */
static int64_t offset_prev = 0;         /* coordinate of prev_row[0] */

/* set a single bit in the global cache (0 → clear, >0 → set) */
static inline void cache_set(idx_t pos, seq_t val)
{
    idx_t w = pos >> 6;                /* divide by 64 */
    idx_t b = pos & 63;                /* remainder */
    if (w >= cache_words) {
        size_t new_words = cache_words ? (cache_words << 1) : 64;
        while (new_words <= w) new_words <<= 1;
        uint64_t *new_cache = (uint64_t *)realloc(cache_bits, new_words * sizeof(uint64_t));
        for (size_t i = cache_words; i < new_words; ++i) new_cache[i] = 0;
        cache_bits = new_cache;
        cache_words = new_words;
    }
    if (val)
        cache_bits[w] |= ((uint64_t)1 << b);
    else
        cache_bits[w] &= ~((uint64_t)1 << b);
}

/* read a single bit from the global cache */
static inline seq_t cache_get(idx_t pos)
{
    idx_t w = pos >> 6;
    idx_t b = pos & 63;
    if (w >= cache_words) return 0;
    return (seq_t)((cache_bits[w] >> b) & 1);
}

/* compute the nth element of the sequence */
seq_t a(idx_t n)
{
    /* initialise on first call */
    if (cached_cells == 0) {
        prev_len = 1;
        prev_row = (uint8_t *)malloc(prev_len);
        prev_row[0] = 1;              /* row 0: single ON cell */
        cache_set(0, 1);
        cached_cells = 1;
        offset_prev = 0;              /* coordinate of prev_row[0] */
    }

    /* generate rows until the requested index is cached */
    while (cached_cells <= n) {
        size_t next_len = prev_len + 2;
        uint8_t *next_row = (uint8_t *)malloc(next_len);
        int64_t offset_next = offset_prev - 1;
        int64_t min_coord_prev = offset_prev;
        int64_t max_coord_prev = offset_prev + (int64_t)prev_len - 1;

        for (size_t j = 0; j < next_len; ++j) {
            int64_t coord = offset_next + j;
            uint8_t left  = 0, center = 0, right = 0;

            int64_t lc = coord - 1;
            if (lc >= min_coord_prev && lc <= max_coord_prev)
                left = prev_row[lc - offset_prev];

            int64_t cc = coord;
            if (cc >= min_coord_prev && cc <= max_coord_prev)
                center = prev_row[cc - offset_prev];

            int64_t rc = coord + 1;
            if (rc >= min_coord_prev && rc <= max_coord_prev)
                right = prev_row[rc - offset_prev];

            uint8_t pattern = (left << 2) | (center << 1) | right;
            uint8_t cell = (uint8_t)((78U >> pattern) & 1U);

            next_row[j] = cell;
            cache_set(cached_cells, cell);
            ++cached_cells;
        }

        free(prev_row);
        prev_row = next_row;
        prev_len = next_len;
        offset_prev = offset_next;
    }

    return cache_get(n);
}
